/*
 * Neural forecasting INFERENCE kernel -- CUDA C reference.
 *
 * A 2-layer MLP (D_IN -> H -> 1, tanh hidden) evaluated over N feature vectors, the
 * compute profile of financial-AI inference: small dense matrix-vector products plus
 * a transcendental activation, embarrassingly parallel over the batch. Each thread
 * runs the full forward pass for its samples and accumulates the scalar output; we
 * report the mean output as a consistency value.
 *
 * Weights and inputs are generated by an index-addressed integer formula (the same
 * uniform() bit trick as the MC kernels) so they are bit-identical to the Mojo
 * version; an untimed init kernel fills the weights once into global memory, then the
 * timed inference kernel reuses them.
 *
 * Compile: nvcc -O3 -arch=sm_89 -use_fast_math mlp_cuda.cu -o mlp_cuda
 */
#include <cuda_runtime.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define BLOCK_SIZE 128
#define N_THREADS  (1 << 18)
#define GRID_SIZE  (N_THREADS / BLOCK_SIZE)
#define D_IN 16
#define H    64
#define NW   (H*D_IN + H + H + 1)        /* W1, b1, W2, b2 */

#define CHECK(call) do { cudaError_t e=(call); if(e!=cudaSuccess){ \
  fprintf(stderr,"CUDA %s:%d %s\n",__FILE__,__LINE__,cudaGetErrorString(e)); exit(1);} } while(0)

__device__ __forceinline__ unsigned lcg(unsigned s){ return s*1664525u+1013904223u; }
__device__ __forceinline__ float uf(unsigned s){ return __uint_as_float((s>>9)|0x3F800000u)-1.0f; }
/* deterministic value in (-1,1) from an integer key */
__device__ __forceinline__ float rnd(unsigned key){ return 2.0f*uf(lcg(key^0x9E3779B9u))-1.0f; }

__global__ void init_weights(float* W){
    int t = blockIdx.x*blockDim.x + threadIdx.x;
    for (int k = t; k < NW; k += gridDim.x*blockDim.x)
        W[k] = rnd((unsigned)k) * 0.25f;          /* small init, scale 0.25 */
}

__global__ void mlp_kernel(const float* __restrict__ W, float* partials, long long n){
    int tid = blockIdx.x*blockDim.x + threadIdx.x;
    if (tid >= N_THREADS) return;
    const float* W1 = W;            /* [H][D_IN] */
    const float* b1 = W1 + H*D_IN;  /* [H]       */
    const float* W2 = b1 + H;       /* [H]       */
    const float  b2 = W2[H];        /* scalar    */
    float acc = 0.0f;
    for (long long i = tid; i < n; i += N_THREADS) {
        float x[D_IN];
        #pragma unroll
        for (int d = 0; d < D_IN; d++) x[d] = rnd((unsigned)(i*D_IN + d + 1));
        float out = b2;
        #pragma unroll 4
        for (int h = 0; h < H; h++) {
            float a = b1[h];
            #pragma unroll
            for (int d = 0; d < D_IN; d++) a += W1[h*D_IN + d] * x[d];
            out += W2[h] * tanhf(a);
        }
        acc += out;
    }
    partials[tid] = acc;
}

double wall_ms(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec*1e3+t.tv_nsec*1e-6; }
static int dcmp(const void*a,const void*b){ double d=*(const double*)a-*(const double*)b; return (d>0)-(d<0);}
static double vmin(const double*a,int n){ double m=a[0]; for(int i=1;i<n;i++) if(a[i]<m)m=a[i]; return m;}
static double vstd(const double*a,int n){ double mu=0; for(int i=0;i<n;i++)mu+=a[i]; mu/=n; double s=0;
  for(int i=0;i<n;i++){double d=a[i]-mu; s+=d*d;} return sqrt(s/n);}
static double vmed(const double*a,int n){ double*b=(double*)malloc(n*sizeof(double));
  for(int i=0;i<n;i++)b[i]=a[i]; qsort(b,n,sizeof(double),dcmp); double m=b[n/2]; free(b); return m;}

int main(void){
    CHECK(cudaSetDevice(0));
    cudaDeviceProp p; CHECK(cudaGetDeviceProperties(&p,0));
    printf("GPU 0: %s   (MLP inference, %d->%d->1, tanh)\n\n", p.name, D_IN, H);

    float *dW=NULL, *dP=NULL; CHECK(cudaMalloc(&dW,NW*sizeof(float)));
    CHECK(cudaMalloc(&dP,(size_t)N_THREADS*sizeof(float)));
    float* hP=(float*)malloc((size_t)N_THREADS*sizeof(float));
    init_weights<<<64,128>>>(dW); CHECK(cudaDeviceSynchronize());   /* untimed */

    long long sizes[]={1000000LL,10000000LL,100000000LL};
    const int reps=50; double times[64];
    printf("%14s  %10s  %12s  %10s  %10s\n","Samples","min(ms)","median(ms)","std(ms)","MeanOut");
    printf("--------------------------------------------------------------------\n");
    for(int s=0;s<3;s++){
        long long n=sizes[s];
        for(int w=0;w<5;w++) mlp_kernel<<<GRID_SIZE,BLOCK_SIZE>>>(dW,dP,n);
        CHECK(cudaDeviceSynchronize());
        for(int r=0;r<reps;r++){ double t0=wall_ms();
            mlp_kernel<<<GRID_SIZE,BLOCK_SIZE>>>(dW,dP,n);
            CHECK(cudaDeviceSynchronize()); times[r]=wall_ms()-t0; }
        CHECK(cudaMemcpy(hP,dP,(size_t)N_THREADS*sizeof(float),cudaMemcpyDeviceToHost));
        double tot=0; for(int j=0;j<N_THREADS;j++) tot+=(double)hP[j];
        printf("%14lld  %10.4f  %12.4f  %10.4f  %10.6f\n",
               n,vmin(times,reps),vmed(times,reps),vstd(times,reps),tot/(double)n);
    }
    CHECK(cudaFree(dW)); CHECK(cudaFree(dP)); free(hP); return 0;
}
